    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int ans = 0, l = 0, n = 0, r = 0, x = 0;
    // 读取小写字符串，STDIO 中 - 由 readstr 转成空串。
    n = readstr(a);
    ans = 0;
    l = 0;
    for (r = 0; r < n; r += 1) {
        x = a[r];
        // 只有上次出现仍在当前窗口内时，才把左边界推到其后一位。
        if (b[x] > l) {
            l = b[x];
        }
        // 记录位置加一，让零表示从未出现。
        b[x] = (r + 1);
        ans = mx(ans, ((r - l) + 1));
    }
    // ans 汇总每个右端点的最长无重复窗口长度。
    emit(ans);
    return 0;
}

