impl Solution {
    pub fn length_of_longest_substring(s: String) -> i32 {
        // 题目是小写 ASCII 字符，用字节编码对应位置表下标。
        let mut a: Vec<i32> = s.bytes().map(|v| v as i32).collect();
        let n = a.len() as i32;
        let mut b = vec![0i32; 20000];
        let mut d = vec![0i32; 20000];
        let mut e = vec![0i32; 20000];
