        while r < n {
            x = a[(r) as usize];
            // 仅当旧字符仍在窗口中，才把 l 推到它的后一位。
            if (b[(x) as usize] > l) {
                l = b[(x) as usize];
            }
            b[(x) as usize] = (r + 1);
            ans = mx(ans, ((r - l) + 1));
